import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public class EnrollmentRollupTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final List<String> ROWS = Arrays.asList(
            "MATH | Calculus | 100 | 31",
            "MATH | Logic    | 100 | 9",
            "MATH | Topology | 300 | 4",
            "ART  | Clay     | 200 | 12",
            "ART  | Clay     | 200 | 3",
            "CS   | Compilers| 400 | 17");

    public static void main(String[] args) {
        Map<String, Map<Integer, Integer>> levels;
        try {
            levels = EnrollmentRollup.byDepartmentAndLevel(ROWS);
        } catch (RuntimeException e) {
            levels = null;
            System.out.println("FAIL  byDepartmentAndLevel threw " + e.getClass().getSimpleName());
            failures++;
        }
        check("department count", 3, levels == null ? -1 : levels.size());
        check("MATH level 100 total", Integer.valueOf(40),
                levels == null || levels.get("MATH") == null ? null : levels.get("MATH").get(100));
        check("MATH level 300 total", Integer.valueOf(4),
                levels == null || levels.get("MATH") == null ? null : levels.get("MATH").get(300));
        check("MATH has two levels", 2,
                levels == null || levels.get("MATH") == null ? -1 : levels.get("MATH").size());
        check("ART level 200 adds duplicate courses", Integer.valueOf(15),
                levels == null || levels.get("ART") == null ? null : levels.get("ART").get(200));
        check("inner map is sorted", "{100=40, 300=4}",
                levels == null ? "null" : String.valueOf(levels.get("MATH")));
        check("no level 999", null,
                levels == null || levels.get("CS") == null ? null : levels.get("CS").get(999));

        Map<String, List<String>> courses;
        try {
            courses = EnrollmentRollup.coursesByDepartment(ROWS);
        } catch (RuntimeException e) {
            courses = null;
            System.out.println("FAIL  coursesByDepartment threw " + e.getClass().getSimpleName());
            failures++;
        }
        check("MATH courses sorted", "[Calculus, Logic, Topology]",
                courses == null ? "null" : String.valueOf(courses.get("MATH")));
        check("duplicate course listed once", "[Clay]",
                courses == null ? "null" : String.valueOf(courses.get("ART")));
        check("course department count", 3, courses == null ? -1 : courses.size());
        check("unknown department", null, courses == null ? null : courses.get("PHYS"));

        check("empty input gives empty map", 0,
                EnrollmentRollup.byDepartmentAndLevel(Collections.<String>emptyList()).size());
        check("empty input gives empty course map", 0,
                EnrollmentRollup.coursesByDepartment(Collections.<String>emptyList()).size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

