import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;

public class EnrollmentRollup {

    public static Map<String, Map<Integer, Integer>> byDepartmentAndLevel(List<String> rows) {
        return rows.stream()
                .map(EnrollmentRollup::fields)
                .collect(Collectors.groupingBy(
                        f -> f[0],
                        TreeMap::new,
                        Collectors.groupingBy(
                                f -> Integer.parseInt(f[2]),
                                TreeMap::new,
                                Collectors.summingInt(f -> Integer.parseInt(f[3])))));
    }

    public static Map<String, List<String>> coursesByDepartment(List<String> rows) {
        return rows.stream()
                .map(EnrollmentRollup::fields)
                .collect(Collectors.groupingBy(
                        f -> f[0],
                        TreeMap::new,
                        Collectors.mapping(
                                f -> f[1],
                                Collectors.collectingAndThen(
                                        Collectors.toCollection(TreeSet::new),
                                        ArrayList::new))));
    }

    private static String[] fields(String row) {
        String[] parts = row.split("\\|");
        for (int i = 0; i < parts.length; i++) {
            parts[i] = parts[i].trim();
        }
        return parts;
    }
}
